// AI stand-in, all in one (chat + camera slides + open questions + override). Paste into the console of your Google Meet tab. Generated by all/build.mjs; do not edit.
// Logging: every line has a timestamp. Pass done/total for anything that runs in steps.
(function () {
  const NS = (window.__standin = window.__standin || {});

  function isoLocal() {
    const d = new Date();
    const off = -d.getTimezoneOffset();
    const sign = off >= 0 ? '+' : '-';
    const hh = String(Math.floor(Math.abs(off) / 60)).padStart(2, '0');
    const mm = String(Math.abs(off) % 60).padStart(2, '0');
    const local = new Date(d.getTime() - d.getTimezoneOffset() * 60000);
    return local.toISOString().slice(0, -1) + sign + hh + ':' + mm;
  }

  NS.isoLocal = isoLocal;
  NS.logLines = [];
  NS.log = function (msg, done, total) {
    const prog = total != null ? ' [' + done + '/' + total + ']' : '';
    const line = isoLocal() + prog + ' [standin] ' + msg;
    NS.logLines.push(line);
    if (NS.logLines.length > 500) NS.logLines.shift();
    console.log(line);
  };
})();

// Settings. Saved in the page's local storage; the Meet tab only.
(function () {
  const NS = (window.__standin = window.__standin || {});
  const KEY = 'standin.config';

  const defaults = {
    enabled: true, // swap camera and mic. Reload the call to change.
    userName: 'Eswar',
    names: ['eswar', 'ishwar', 'eshwar', 'iswar', 'pothuri', 'poturi', 'sai'],
    threshold: 75, // answer only at or above this confidence (0-100)
    disclosure: true, // first reply says it is an AI stand-in
    brain: 'stub', // 'stub' (demo rules), 'claude' (extension + API key) or 'relay' (relay.ps1 on this laptop)
    relayUrl: 'http://127.0.0.1:8765',
    realVoice: true, // use the Windows voice through the relay when it is running
    override: true, // when it would hold a yes/no question, show Yes/No buttons in the panel for a few seconds
    overrideWaitMs: 20000,
    autoRelay: true, // if the relay is running, use it instead of the demo rules
    model: 'claude-sonnet-5-5',
    heldLine: 'I will confirm after the meeting.',
    captionDebounceMs: 1200,
    ignoreOwnSpeech: true, // do not answer captions from your own mic (speaker "You")
    camera: true, // standin-all.js: show answers as slides on your camera
    openAnswers: true, // answer open questions from your notes (chat and slides) when sure enough
    slideStepMs: 5000, // each slide of an open answer
    slideHoldMs: 9000, // how long a finished answer stays on the camera
    stubOpen: [], // demo answers for open questions when no relay: [{when, confidence, chat, slides, chart}]
    duplicateWindowMs: 15000,
    // Data chart: say "stand-in, chart <topic>" and the camera shows a chart of public data, with its source.
    dataChart: true,
    chartHoldMs: 20000, // how long the chart stays on the camera
    chartStepMs: 9000, // chart, then a one-line summary
    chartChat: true, // also post one labelled line with the source in the Meet chat
    contextBudget: 9000, // characters of your notes sent with each question
    contextRefreshMs: 60000, // the relay's context folder is re-read at most this often
    chartRepeatMs: 300000, // the same topic is not charted again from speech for this long (standin.chart() always works)
    chartMinPoints: 3, // fewer data points than this is not charted
    // Context pack: what Claude may use. Plain text for 'claude'; rules for 'stub'.
    contextPack: '',
    stubRules: [],
  };

  let saved = {};
  try {
    saved = JSON.parse(localStorage.getItem(KEY) || '{}') || {};
  } catch (e) {
    saved = {};
  }

  NS.config = Object.assign({}, defaults, saved);
  NS.saveConfig = function () {
    try {
      localStorage.setItem(KEY, JSON.stringify(NS.config));
    } catch (e) {
      /* storage can be blocked; the stand-in still works for this call */
    }
  };
})();

// The brain: spot a question meant for the user, decide, apply the confidence gate, then act.
(function () {
  const NS = (window.__standin = window.__standin || {});
  const AUX = '(do|does|did|is|are|was|were|am|can|could|will|would|should|shall|have|has|had|may|might|must)';
  const SUBJ = '(we|you|i|it|this|that|the|they|there|he|she|everyone|anyone|all|a|an|my|our|your|these|those)';
  const AUX_RE = new RegExp('^' + AUX + '\\s+' + SUBJ + '\\b');
  const DET_RE = new RegExp('^' + AUX + '\\s+(the|a|an|my|our|your|these|those|everyone|anyone|all|there)\\b');
  const WH_RE = /^(what|how|why|when|where|who|which|whom|whose)\b/;
  const OPEN_PHRASES = /(walk us through|walk me through|explain|tell us|tell me|describe|your thoughts|what do you think|how do you see|give us an update|any update)/;
  const YN_PHRASES = /(sound good|good to go|okay with|ok with|fine with|do you agree|are you ready|ready to go|make sense|works? for you)/;
  const FILLERS = new Set(['so', 'okay', 'ok', 'well', 'now', 'right', 'hey', 'hi', 'quick', 'also', 'next', 'and', 'but', 'then', 'thanks', 'thank']);

  function editDistance(a, b) {
    const m = a.length;
    const n = b.length;
    const d = [];
    for (let i = 0; i <= m; i++) d[i] = [i];
    for (let j = 0; j <= n; j++) d[0][j] = j;
    for (let i = 1; i <= m; i++) {
      for (let j = 1; j <= n; j++) {
        d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
      }
    }
    return d[m][n];
  }

  function isName(word) {
    const w = word.toLowerCase();
    return NS.config.names.some(function (n) {
      if (w === n) return true;
      return w.length >= 5 && n.length >= 5 && editDistance(w, n) <= 1;
    });
  }

  function sentencesOf(text) {
    const parts = text.match(/[^.?!]+[.?!]*/g) || [];
    return parts.map(function (s) { return s.trim(); }).filter(Boolean);
  }

  function hasName(s) {
    return (s.match(/[A-Za-z]+/g) || []).some(isName);
  }

  function otherVocative(s) {
    const m = s.match(/^\s*([A-Z][a-z]+),/);
    return !!m && !FILLERS.has(m[1].toLowerCase()) && !isName(m[1]);
  }

  // Returns 'yesno', 'open' or 'none' for one sentence that contains the user's name.
  function classify(sentence) {
    const raw = sentence.toLowerCase();
    const core = raw.replace(/[a-z]+/g, function (w) { return isName(w) ? '' : w; });
    const clauses = core
      .split(/[,;:\u2014-]/)
      .map(function (c) { return c.replace(/[?!.]/g, '').trim(); })
      .filter(Boolean);
    const endsQ = /\?\s*$/.test(sentence.trim());
    // "Did Eswar send it?" asks about him, not to him.
    if (new RegExp('(^|[,;:\\u2014-]\\s*)' + AUX + '\\s+(' + NS.config.names.join('|') + ')\\b', 'i').test(raw)) return 'none';
    // "Eswar, did the report go out" with no question mark (live captions often drop it): aux right after the name and a comma is a question.
    const vocAux = new RegExp('^\\s*(' + NS.config.names.join('|') + ')\\s*,\\s*' + AUX + '\\b', 'i').test(raw);
    if (OPEN_PHRASES.test(core)) return 'open';
    if (clauses.some(function (c) { return WH_RE.test(c); })) return 'open';
    if (
      YN_PHRASES.test(core) ||
      clauses.some(function (c) {
        if (!AUX_RE.test(c)) return false;
        // "has the latest numbers" is a statement unless it ends with a question mark.
        return endsQ || vocAux || !DET_RE.test(c);
      })
    ) return 'yesno';
    return endsQ ? 'open' : 'none';
  }

  function wordCount(s) {
    return (s.match(/[A-Za-z]+/g) || []).length;
  }

  // text -> { addressed, kind, question }
  function detect(text) {
    const none = { addressed: false, kind: 'none', question: '' };
    const sents = sentencesOf(text || '');
    for (let i = 0; i < sents.length; i++) {
      const s = sents[i];
      if (!hasName(s) || otherVocative(s)) continue;
      let kind = classify(s);
      let q = s;
      const nameOnly = (s.match(/[A-Za-z]+/g) || []).filter(function (w) { return !isName(w); }).length === 0;
      if (nameOnly || (kind === 'none' && wordCount(s) <= 3)) {
        // The name alone ("Eswar?"): the question is the sentence before or after it.
        const prev = sents[i - 1];
        const next = sents[i + 1];
        if (prev && !otherVocative(prev) && classify(prev) !== 'none') {
          kind = classify(prev);
          q = prev;
        } else if (next && !otherVocative(next) && classify(next) !== 'none') {
          kind = classify(next);
          q = next;
        }
      }
      if (kind !== 'none') return { addressed: true, kind: kind, question: q };
    }
    return none;
  }

  // ---- Deciding ----

  function parseDecision(text) {
    const bad = { answer: 'unsure', confidence: 0, reason: 'I could not read the answer.' };
    if (!text) return bad;
    const m = String(text).match(/\{[\s\S]*\}/);
    if (!m) return bad;
    try {
      const o = JSON.parse(m[0]);
      const answer = String(o.answer || '').toLowerCase();
      if (answer !== 'yes' && answer !== 'no' && answer !== 'unsure') return bad;
      let conf = Number(o.confidence);
      if (!isFinite(conf)) return bad;
      conf = Math.max(0, Math.min(100, Math.round(conf)));
      const reason = String(o.reason || '').trim().slice(0, 200);
      return { answer: answer, confidence: answer === 'unsure' ? Math.min(conf, 50) : conf, reason: reason || 'No reason given.' };
    } catch (e) {
      return bad;
    }
  }

  function stubDecide(q) {
    const rules = NS.config.stubRules || [];
    for (let i = 0; i < rules.length; i++) {
      if (new RegExp(rules[i].when, 'i').test(q)) {
        return { answer: rules[i].answer, confidence: rules[i].confidence, reason: rules[i].reason };
      }
    }
    return { answer: 'unsure', confidence: 40, reason: 'None of my notes cover this.' };
  }

  // Open questions: a short answer for the chat, one to three slides, and optionally a chart.
  const UNSURE_OPEN = { answer: 'unsure', confidence: 0, reason: 'This is an open question.' };
  function cut(x, n) { return String(x == null ? '' : x).replace(/\s+/g, ' ').trim().slice(0, n); }
  function parseOpen(text) {
    if (!text) return UNSURE_OPEN;
    const m = String(text).match(/\{[\s\S]*\}/);
    if (!m) return UNSURE_OPEN;
    try {
      const o = JSON.parse(m[0]);
      if (String(o.answer || '').toLowerCase() !== 'open') return UNSURE_OPEN;
      let conf = Number(o.confidence);
      if (!isFinite(conf)) return UNSURE_OPEN;
      conf = Math.max(0, Math.min(100, Math.round(conf)));
      const chat = cut(o.chat, 300);
      const slides = (Array.isArray(o.slides) ? o.slides : []).slice(0, 3)
        .map(function (s) { return { title: cut(s && s.title, 60), text: cut(s && s.text, 220) }; })
        .filter(function (s) { return s.title || s.text; });
      if (!chat || !slides.length) return UNSURE_OPEN;
      let chart = null;
      const c = o.chart;
      if (c && (c.type === 'pie' || c.type === 'bar') && Array.isArray(c.items)) {
        const items = c.items.slice(0, 6)
          .map(function (i) { return { label: cut(i && i.label, 30), value: Number(i && i.value) }; })
          .filter(function (i) { return i.label && isFinite(i.value) && i.value >= 0; });
        if (items.length >= 2) chart = { type: c.type, title: cut(c.title, 60), items: items };
      }
      return { answer: 'open', confidence: conf, reason: chat, chat: chat, slides: slides, chart: chart };
    } catch (e) {
      return UNSURE_OPEN;
    }
  }
  function stubOpen(q) {
    const rules = NS.config.stubOpen || [];
    for (let i = 0; i < rules.length; i++) {
      if (new RegExp(rules[i].when, 'i').test(q)) {
        return parseOpen(JSON.stringify({ answer: 'open', confidence: rules[i].confidence, chat: rules[i].chat, slides: rules[i].slides, chart: rules[i].chart || null }));
      }
    }
    return UNSURE_OPEN;
  }
  function buildOpenPrompt(q, recent) {
    const name = NS.config.userName;
    const system =
      'You are the brain of a labelled AI stand-in that attends a meeting for ' + name + '. Someone asked ' + name + ' an open question. ' +
      'Use only the context pack below. If it does not clearly cover the question, reply {"answer":"unsure","confidence":0}. ' +
      'Otherwise reply with JSON only: {"answer":"open","confidence":0-100,"chat":"at most 2 short sentences, first person",' +
      '"slides":[{"title":"at most 6 words","text":"at most 25 words"}],"chart":null or {"type":"pie" or "bar","title":"...","items":[{"label":"...","value":number}]}}. ' +
      'Use 1 to 3 slides. Add a chart only if the context pack has real numbers for it; never invent numbers. ' +
      'Confidence is how sure you are that ' + name + ' himself would say this.';
    const user = 'Context pack:\n' + (NS.config.contextPack || '(empty)') + '\n\nRecent meeting lines:\n' + (recent || '(none)') + '\n\nQuestion for ' + name + ': ' + q;
    return { model: NS.config.model, max_tokens: 500, system: system, messages: [{ role: 'user', content: user }] };
  }

  function buildPrompt(q, recent) {
    const name = NS.config.userName;
    const system =
      'You are the decision brain of a labelled AI stand-in that attends a meeting for ' + name + '. ' +
      'You answer only yes/no questions put to ' + name + '. Use only the context pack below. ' +
      'If the context pack does not clearly settle the question, answer "unsure" with low confidence. ' +
      'Confidence is how sure you are that ' + name + ' himself would give this answer. ' +
      'Reply with JSON only: {"answer":"yes"|"no"|"unsure","confidence":0-100,"reason":"one plain sentence, first person, at most 25 words"}.';
    const user =
      'Context pack:\n' + (NS.config.contextPack || '(empty)') +
      '\n\nRecent meeting lines:\n' + (recent || '(none)') +
      '\n\nQuestion for ' + name + ': ' + q;
    return { model: NS.config.model, max_tokens: 200, system: system, messages: [{ role: 'user', content: user }] };
  }

  // Page -> extension bridge -> background -> Anthropic API. The key never enters the Meet page.
  let nextId = 1;
  NS.llm = function (body) {
    return new Promise(function (resolve, reject) {
      const id = nextId++;
      const timer = setTimeout(function () {
        window.removeEventListener('message', onMsg);
        reject(new Error('timed out'));
      }, 20000);
      function onMsg(ev) {
        const d = ev.data;
        if (!d || d.source !== 'standin-bridge' || d.id !== id) return;
        clearTimeout(timer);
        window.removeEventListener('message', onMsg);
        if (d.ok) resolve(d.text);
        else reject(new Error(d.error || 'failed'));
      }
      window.addEventListener('message', onMsg);
      window.postMessage({ source: 'standin', type: 'llm', id: id, body: body }, '*');
    });
  };

  // Relay: a small program on this laptop (relay.ps1) that holds the key and calls the model.
  // Chrome stops Meet from calling this laptop directly (local-network permission). So we open a small
  // relay window from the relay itself and pass messages to it. No direct call, no permission needed.
  const bridge = { win: null, pending: {}, nextId: 1, listening: false };
  function relayOrigin() {
    try {
      return new URL(NS.config.relayUrl).origin;
    } catch (e) {
      return '';
    }
  }
  function onBridgeMessage(ev) {
    if (ev.origin !== relayOrigin()) return;
    const d = ev.data;
    if (!d || d.source !== 'standin-bridge-res') return;
    const p = bridge.pending[d.id];
    if (!p) return;
    delete bridge.pending[d.id];
    clearTimeout(p.timer);
    if (d.ok) p.resolve(d);
    else p.reject(new Error(d.error || 'relay error'));
  }
  NS.openBridge = function (reload) {
    if (!bridge.listening) {
      window.addEventListener('message', onBridgeMessage);
      bridge.listening = true;
    }
    if (bridge.win && !bridge.win.closed) {
      if (reload) {
        try { bridge.win.location.href = NS.config.relayUrl + '/bridge'; } catch (e) { /* ignore */ }
        lastRelayCheck = 0;
        relayUp = false;
      }
      return true;
    }
    bridge.win = window.open(NS.config.relayUrl + '/bridge', 'standin-relay', 'popup,width=420,height=260');
    if (!bridge.win) {
      NS.log('relay window blocked: allow pop-ups for Meet, then press Connect relay in the panel');
      return false;
    }
    NS.log('relay window opened');
    return true;
  };
  function bridgeSend(kind, body, ms) {
    return new Promise(function (resolve, reject) {
      if (!bridge.win || bridge.win.closed) return reject(new Error('relay window is not open'));
      const id = bridge.nextId++;
      const timer = setTimeout(function () {
        delete bridge.pending[id];
        reject(new Error('relay did not answer'));
      }, ms);
      bridge.pending[id] = { resolve: resolve, reject: reject, timer: timer };
      try {
        bridge.win.postMessage({ source: 'standin-bridge-req', id: id, kind: kind, body: body }, relayOrigin());
      } catch (e) {
        clearTimeout(timer);
        delete bridge.pending[id];
        reject(e);
      }
    });
  }
  let lastRelayCheck = 0;
  let relayUp = false;
  async function checkRelay() {
    // While the relay is up, no checks. While it is down, at most one check every 15 seconds.
    if (relayUp && bridge.win && !bridge.win.closed) return true;
    if (Date.now() - lastRelayCheck < 15000) return false;
    lastRelayCheck = Date.now();
    try {
      await bridgeSend('ping', null, 3000);
      relayUp = true;
    } catch (e) {
      relayUp = false;
    }
    NS.log(relayUp ? 'relay found: live brain on' : 'relay not found: using demo answers');
    return relayUp;
  }
  // For other modules (the data chart): ask the relay for anything, and check it is up.
  NS.relayCall = function (kind, body, ms) { return bridgeSend(kind, body, ms || 20000); };
  NS.relayReady = function () { return checkRelay(); };
  async function relayDecide(q, recent) {
    const pack = NS.context ? await NS.context.packFor(q, recent) : null;
    const d = await bridgeSend('decide', { question: q, recent: recent || '', userName: NS.config.userName, pack: pack }, 12000);
    return parseDecision(JSON.stringify(d.json));
  }

  // Real voice: the relay turns the line into speech with the Windows voice. If the relay is down, the dummy voice is used.
  NS.tts = async function (text) {
    if (!NS.config.realVoice || !relayUp || !bridge.win || bridge.win.closed) return null;
    const d = await bridgeSend('tts', { text: text }, 8000);
    const bin = atob(d.json.wav);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return NS.decodeAudio(bytes.buffer);
  };

  async function decide(q, recent) {
    const cfg = NS.config;
    let useRelay = cfg.brain === 'relay';
    if (!useRelay && cfg.brain === 'stub' && cfg.autoRelay) useRelay = await checkRelay();
    if (useRelay) {
      try {
        return await relayDecide(q, recent);
      } catch (e) {
        NS.log('relay failed: ' + e.message);
        return { answer: 'unsure', confidence: 0, reason: 'My notes were not reachable.' };
      }
    }
    if (cfg.brain === 'claude') {
      try {
        const text = await NS.llm(buildPrompt(q, recent));
        return parseDecision(text);
      } catch (e) {
        NS.log('brain failed: ' + e.message);
        return { answer: 'unsure', confidence: 0, reason: 'My notes were not reachable.' };
      }
    }
    return stubDecide(q);
  }

  async function decideOpen(q, recent) {
    const cfg = NS.config;
    let useRelay = cfg.brain === 'relay';
    if (!useRelay && cfg.brain === 'stub' && cfg.autoRelay) useRelay = await checkRelay();
    if (useRelay) {
      try {
        const pack = NS.context ? await NS.context.packFor(q, recent) : null;
        const d = await bridgeSend('answer', { question: q, recent: recent || '', userName: cfg.userName, pack: pack }, 25000);
        return parseOpen(JSON.stringify(d.json));
      } catch (e) {
        NS.log('relay failed: ' + e.message);
        return UNSURE_OPEN;
      }
    }
    if (cfg.brain === 'claude') {
      try {
        return parseOpen(await NS.llm(buildOpenPrompt(q, recent)));
      } catch (e) {
        NS.log('brain failed: ' + e.message);
        return UNSURE_OPEN;
      }
    }
    return stubOpen(q);
  }

  // ---- Acting ----

  const events = (NS.events = new EventTarget());
  NS.history = [];
  const recentQuestions = [];
  let busy = false;
  let disclosed = false;

  function emit(type, detail) {
    events.dispatchEvent(new CustomEvent(type, { detail: detail }));
  }

  async function say(text, meta) {
    // standin-all.js: the answer goes into the Meet chat and onto the camera as a slide. No face, no voice.
    if (NS.config.output === 'all') {
      if (NS.slides && meta) NS.slides.show(meta, text);
      const p = NS.chat.post(text);
      NS.lastSpeech = p;
      await p;
      return;
    }
    // Chat-only mode (standin-chat.js): the answer goes into the Meet chat. No face, no voice.
    if (NS.config.output === 'chat') {
      await NS.chat.post(text);
      return;
    }
    NS.avatar.setSubtitle(text);
    const p = NS.speak(text);
    NS.lastSpeech = p;
    try {
      await p;
    } finally {
      NS.avatar.setSubtitle('');
    }
  }

  // Handle one utterance. Resolves when the decision is made and the stand-in has started to act.
  NS.handleUtterance = async function (text, recent) {
    const t0 = performance.now();
    const d = detect(text);
    if (!d.addressed) return { handled: false, reason: 'not for me' };

    const now = Date.now();
    const key = d.question.toLowerCase().replace(/[^a-z ]/g, '').trim();
    while (recentQuestions.length && now - recentQuestions[0].at > NS.config.duplicateWindowMs) recentQuestions.shift();
    if (recentQuestions.some(function (r) { return r.key === key; })) return { handled: false, reason: 'duplicate' };
    if (busy) return { handled: false, reason: 'busy' };
    recentQuestions.push({ key: key, at: now });
    busy = true;
    let keepBusy = false;
    try {
      NS.log('question for me (' + d.kind + '): ' + d.question);
      emit('question', { question: d.question, kind: d.kind });
      let decision;
      if (d.kind === 'open') {
        decision = NS.config.openAnswers ? await decideOpen(d.question, recent || '') : UNSURE_OPEN;
      } else {
        decision = await decide(d.question, recent || '');
      }
      const tDecided = performance.now();
      const yes = decision.answer === 'yes' || decision.answer === 'no';
      const openOK = decision.answer === 'open' && decision.confidence >= NS.config.threshold;
      const answers = (yes && decision.confidence >= NS.config.threshold) || openOK;
      const result = {
        handled: true,
        question: d.question,
        kind: d.kind,
        decision: decision,
        action: openOK ? 'answered' : answers ? (decision.answer === 'yes' ? 'nod' : 'shake') : 'held',
        decidedMs: Math.round(tDecided - t0),
        at: NS.isoLocal(),
      };
      let line;
      if (openOK) {
        result.open = { slides: decision.slides, chart: decision.chart };
        line = decision.chat;
      } else if (answers) {
        if (NS.avatar) NS.avatar.setPose(decision.answer === 'yes' ? 'nod' : 'shake');
        line = (decision.answer === 'yes' ? 'Yes. ' : 'No. ') + decision.reason;
      } else {
        const askYou = NS.config.override && d.kind !== 'open';
        line = askYou ? 'Let me check with ' + NS.config.userName + '.' : NS.config.heldLine;
        if (askYou) result.override = 'asked';
        emit('held', result);
      }
      if (NS.config.disclosure && !disclosed) {
        disclosed = true;
        line = 'I am an AI stand-in for ' + NS.config.userName + '. ' + line;
        result.disclosed = true;
      }
      result.line = line;
      result.actedMs = Math.round(performance.now() - t0);
      NS.history.unshift(result);
      NS.log(
        'decision ' + decision.answer + ' ' + decision.confidence + '% -> ' + result.action + ' in ' + result.actedMs + ' ms'
      );
      emit('decision', result);
      say(line, result).catch(function (e) {
        NS.log('speech failed: ' + e.message);
      });
      if (result.override === 'asked') {
        keepBusy = true;
        NS.lastOverride = overrideFollowUp(result);
      }
      return result;
    } finally {
      if (!keepBusy) busy = false;
    }
  };

  // Manual override. The panel shows Yes / No for a few seconds; you click one.
  // No click in time: the stand-in says the usual "I will confirm after the meeting." Nothing leaves this laptop.
  let pendingOverride = null;
  NS.override = function (answer) {
    if (!pendingOverride) return false;
    pendingOverride(answer);
    return true;
  };
  async function overrideFollowUp(result) {
    let answer = 'none';
    try {
      await NS.lastSpeech;
      emit('override-request', { question: result.question, waitMs: NS.config.overrideWaitMs });
      answer = await new Promise(function (resolve) {
        const timer = setTimeout(function () { resolve('none'); }, NS.config.overrideWaitMs);
        pendingOverride = function (a) { clearTimeout(timer); resolve(a); };
      });
    } catch (e) {
      NS.log('override failed: ' + e.message);
    }
    pendingOverride = null;
    emit('override-done', {});
    try {
      if (answer === 'yes' || answer === 'no') {
        NS.log('override: ' + answer);
        if (NS.avatar) NS.avatar.setPose(answer === 'yes' ? 'nod' : 'shake');
        result.override = answer;
        result.action = answer === 'yes' ? 'nod' : 'shake';
        result.decision = { answer: answer, confidence: 100, reason: NS.config.userName + ' answered himself.' };
        emit('decision', result);
        await say((answer === 'yes' ? 'Yes. ' : 'No. ') + NS.config.userName + ' has confirmed.', result);
      } else {
        result.override = 'no reply';
        NS.log('override: no answer in time');
        await say(NS.config.heldLine, result);
      }
    } catch (e) {
      NS.log('speech failed: ' + e.message);
    } finally {
      busy = false;
    }
    return answer;
  }

  NS.ask = NS.handleUtterance; // for typed test questions and tests
  NS.brain = { detect: detect, parseDecision: parseDecision, buildPrompt: buildPrompt, parseOpen: parseOpen };
})();

// Your context: every .md and .txt file in brain-test\brain-context (any sub-folders) is available to the stand-in.
// The relay serves the folder (POST /context). For each question this page picks the most relevant pieces, so the notes can be as large
// as you like, and the model only sees the part that matches the question.
//   core files     any file whose name starts with "00" is always included (who you are, standing rules).
//   index          the list of file names with their first line, so the model knows what exists.
//   matching       words in the question are matched against every piece, with a tolerance for misheard words (Viva ~ Veeva).
(function () {
  const NS = (window.__standin = window.__standin || {});
  const STOP = new Set('the and for are was were with that this have has had you your from what when where which who whom how why did does not but can could would should will about into over than then them they their there here been being his her its our out any all one two just also more most some such only very like going get got tell tells told say said want need please eswar stand standing project projects'.split(' '));
  let files = [], chunks = [], idf = {}, loadedAt = 0, loading = null, lastError = '';

  function words(s) {
    return (String(s || '').toLowerCase().match(/[a-z0-9][a-z0-9.%$'-]*[a-z0-9%]|[a-z0-9]/g) || []).filter(function (w) { return w.length >= 3 && !STOP.has(w); });
  }
  function skeleton(w) { return w[0] + w.slice(1).replace(/[aeiouhwy]/g, '').replace(/(.)\1+/g, '$1'); }
  function lev1(a, b) {
    if (Math.abs(a.length - b.length) > 1) return false;
    let i = 0, j = 0, edits = 0;
    while (i < a.length && j < b.length) {
      if (a[i] === b[j]) { i++; j++; continue; }
      if (++edits > 1) return false;
      if (a.length > b.length) i++; else if (a.length < b.length) j++; else { i++; j++; }
    }
    return edits + (a.length - i) + (b.length - j) <= 1;
  }
  // How well does a question word match a word in a piece? 1 exact, 0.7 one typo, 0.5 sounds alike (same first letter and consonants).
  function match(q, t) {
    if (q === t) return 1;
    if (q.length >= 5 && t.length >= 5 && lev1(q, t)) return 0.7;
    if (q.length >= 4 && t.length >= 4 && q[0] === t[0] && skeleton(q).length >= 2 && skeleton(q) === skeleton(t)) return 0.5;
    return 0;
  }

  function splitFile(f) {
    let text = String(f.text || '').replace(/\r/g, '');
    const fm = text.match(/^---\n[\s\S]*?\n---\n/);
    let desc = '';
    if (fm) { const d = fm[0].match(/description:\s*(.+)/); desc = d ? d[1].trim() : ''; text = text.slice(fm[0].length); }
    const title = (text.match(/^#\s+(.+)$/m) || [])[1] || '';
    const first = desc || title || text.trim().split('\n')[0].slice(0, 120);
    const out = [];
    let cur = '';
    text.split(/\n{2,}/).forEach(function (para) {
      para = para.trim(); if (!para) return;
      if (cur && cur.length + para.length > 1100) { out.push(cur); cur = ''; }
      cur += (cur ? '\n\n' : '') + para;
      while (cur.length > 1600) { out.push(cur.slice(0, 1400)); cur = cur.slice(1400); }
    });
    if (cur) out.push(cur);
    return { first: first, chunks: out };
  }

  function build(list) {
    files = []; chunks = [];
    list.forEach(function (f) {
      if (!f || !f.file || typeof f.text !== 'string') return;
      const s = splitFile(f);
      const core = /(^|[\\/])00/.test(f.file);
      files.push({ file: f.file, first: s.first, core: core });
      s.chunks.forEach(function (c, i) {
        const text = '[' + f.file + (s.chunks.length > 1 ? ' part ' + (i + 1) : '') + ']\n' + c;
        const tf = {};
        // the file name counts too, so "Veeva" finds release-second-opinion
        words(f.file.replace(/[\\/._-]/g, ' ') + ' ' + c).forEach(function (w) { tf[w] = (tf[w] || 0) + 1; });
        chunks.push({ file: f.file, text: text, tf: tf, core: core });
      });
    });
    const df = {};
    chunks.forEach(function (c) { Object.keys(c.tf).forEach(function (w) { df[w] = (df[w] || 0) + 1; }); });
    idf = {};
    Object.keys(df).forEach(function (w) { idf[w] = Math.log(1 + chunks.length / df[w]); });
  }

  function score(qwords, c) {
    let s = 0;
    const vocab = Object.keys(c.tf);
    qwords.forEach(function (q) {
      let best = 0, bw = null;
      if (c.tf[q]) { best = 1; bw = q; }
      else for (let i = 0; i < vocab.length; i++) { const m = match(q, vocab[i]); if (m > best) { best = m; bw = vocab[i]; } }
      if (best) s += best * (idf[bw] || idf[q] || 1) * (1 + Math.log(c.tf[bw]));
    });
    return s;
  }

  // Returns { pack, used: [file names], chars } for a question (plus recent meeting lines, which count less).
  function pick(question, recent, budget) {
    budget = budget || NS.config.contextBudget || 9000;
    const qw = words(question), rw = words(recent).filter(function (w) { return qw.indexOf(w) < 0; }).slice(-12);
    const header = 'Files available: ' + files.map(function (f) { return f.file + ' (' + f.first.slice(0, 90) + ')'; }).join('; ').slice(0, 2200);
    let out = header, used = [];
    chunks.filter(function (c) { return c.core; }).forEach(function (c) { if (out.length + c.text.length < budget) { out += '\n\n' + c.text; used.push(c.file); } });
    const ranked = chunks.filter(function (c) { return !c.core; }).map(function (c) {
      return { c: c, s: score(qw, c) + 0.25 * score(rw, c) };
    }).filter(function (r) { return r.s > 0; }).sort(function (a, b) { return b.s - a.s; });
    const top = ranked.length ? ranked[0].s : 0;
    for (let i = 0; i < ranked.length; i++) {
      if (ranked[i].s < top * 0.3) break;
      if (out.length + ranked[i].c.text.length > budget) continue;
      out += '\n\n' + ranked[i].c.text;
      if (used.indexOf(ranked[i].c.file) < 0) used.push(ranked[i].c.file);
    }
    return { pack: out, used: used, chars: out.length };
  }

  async function load(force) {
    if (!force && loadedAt && Date.now() - loadedAt < (NS.config.contextRefreshMs || 60000)) return files.length > 0;
    if (loading) return loading;
    loading = (async function () {
      try {
        const d = await NS.relayCall('context', {}, 20000);
        if (!d.json || !Array.isArray(d.json.files)) throw new Error('no file list');
        build(d.json.files);
        loadedAt = Date.now(); lastError = '';
        NS.log('context: ' + files.length + ' files, ' + chunks.length + ' pieces loaded from the relay');
      } catch (e) {
        loadedAt = Date.now(); lastError = e.message;
        NS.log('context: not available (' + e.message + '); the relay will use brain-pack.txt if it has one');
      }
      loading = null;
      return files.length > 0;
    })();
    return loading;
  }

  // The pack for one question: null if there is no context folder, so the relay falls back to its own file.
  async function packFor(question, recent) {
    const ok = await load(false);
    if (!ok) return null;
    const r = pick(question, recent);
    NS.log('context: question uses ' + r.chars + ' characters from ' + (r.used.join(', ') || 'no file'));
    NS.lastContext = r;
    return r.pack;
  }

  NS.context = { load: load, pick: pick, packFor: packFor, build: build, words: words, match: match, info: function () { return { files: files.length, pieces: chunks.length, error: lastError }; } };
})();

// Reads Meet's live captions from the page. Captions must be switched on in Meet.
// Uses the same page structure as Anand's meetcaptions bookmarklet (tools.s-anand.net/meetcaptions):
// region [role=region][aria-label=Captions], one item per speaker turn (.nMcdL) with the speaker (.NWpY1d) and the text (.ygicle).
// If Meet changes that layout, it falls back to reading the whole region as one block of text.
// Meet's page layout can change without warning.
(function () {
  const NS = (window.__standin = window.__standin || {});
  const SEL = { region: '[role="region"][aria-label="Captions"]', item: '.nMcdL', speaker: '.NWpY1d', text: '.ygicle', avatar: 'img[data-iml], img[src*="googleusercontent.com"]' };
  const turns = new Map(); // element -> { speaker, text, handled, timer, firstAt }
  let observer = null;
  let startedAt = Date.now();
  let blockLast = '';
  let blockTimer = null;
  NS.transcript = []; // [{ speaker, text, at }] merged like Anand's file

  function norm(t) { return String(t || '').replace(/\s+/g, ' ').trim(); }
  function regionEl() {
    const all = Array.from(document.querySelectorAll('[role="region"][aria-label="Captions"], [aria-label*="aption" i]'));
    return all.find(function (e) { return cleanText(e); }) || all[0] || null;
  }
  // Text of a region without its buttons and icons (Meet's caption settings button reads "settings" otherwise).
  function cleanText(el) {
    const c = el.cloneNode(true);
    c.querySelectorAll('button, [role="button"], i, svg, [aria-hidden="true"]').forEach(function (e) { e.remove(); });
    return norm(c.textContent);
  }
  function items() {
    const r = document.querySelector(SEL.region);
    if (!r) return [];
    const byClass = Array.from(r.querySelectorAll(SEL.item));
    if (byClass.length) return byClass;
    return Array.from(r.children).filter(function (e) { return e.querySelector(SEL.avatar); });
  }
  function readTurn(el) {
    const sp = el.querySelector(SEL.speaker) || el.querySelector('span');
    let tx = el.querySelector(SEL.text);
    if (!tx) {
      const divs = Array.from(el.children).filter(function (c) { return c.tagName === 'DIV' && !c.querySelector(SEL.avatar); });
      tx = divs[divs.length - 1];
    }
    const speaker = norm(sp && sp.textContent), text = norm(tx && tx.textContent);
    return speaker && text ? { speaker: speaker, text: text } : null;
  }
  function isSelf(speaker) {
    // Meet labels your own speech "You", or with your full profile name (seen live: "Pothuri Sai Eswar"), so any speaker whose name contains userName counts.
    const s = speaker.toLowerCase(), u = String(NS.config.userName || '').toLowerCase();
    return NS.config.ignoreOwnSpeech !== false && (s === 'you' || /\(you\)\s*$/.test(s) || (u.length >= 3 && s.indexOf(u) >= 0));
  }

  // Add to the transcript: same speaker keeps growing one entry (as in Anand's file).
  function record(speaker, text) {
    const last = NS.transcript[NS.transcript.length - 1];
    if (last && last.speaker === speaker) {
      if (text === last.text || last.text.endsWith(text)) return;
      if (text.indexOf(last.text) === 0) { last.text = text; return; }
      last.text += '\n\n' + text;
      return;
    }
    NS.transcript.push({ speaker: speaker, text: text, at: Date.now() - startedAt });
  }
  function recentLines() {
    return NS.transcript.slice(-6).map(function (t) { return t.speaker + ': ' + t.text.replace(/\s+/g, ' ').slice(-300); }).join('\n');
  }
  function mmss(ms) { const s = Math.floor(ms / 1000); return Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0'); }
  NS.transcriptMarkdown = function () {
    const head = '# ' + (norm(document.title.replace(/^Meet\s*[-\u2013]\s*/, '')) || 'Meeting') + '\n\n- **Started**: ' + new Date(startedAt).toLocaleString() + '\n\n---\n';
    return head + NS.transcript.map(function (t) { return '\n## ' + t.speaker + ' [' + mmss(t.at) + ']\n\n' + t.text + '\n'; }).join('');
  };
  NS.downloadTranscript = function () {
    if (!NS.transcript.length) return false;
    const a = document.createElement('a');
    a.href = URL.createObjectURL(new Blob([NS.transcriptMarkdown()], { type: 'text/markdown' }));
    a.download = 'meet-captions-' + new Date().toISOString().slice(0, 19).replace(/[T:]/g, '-') + '.md';
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(function () { URL.revokeObjectURL(a.href); }, 5000);
    return true;
  };

  function fire(speaker, text) {
    NS.log('caption' + (speaker ? ' (' + speaker + ')' : '') + ': ' + text.slice(-120));
    NS.handleUtterance(text, recentLines()).catch(function (e) { NS.log('caption handling failed: ' + e.message); });
  }

  function scan() {
    const list = items();
    if (list.length) {
      list.forEach(function (el) {
        const t = readTurn(el);
        if (!t) return;
        let st = turns.get(el);
        if (!st) { st = { speaker: t.speaker, text: '', handled: '', timer: null }; turns.set(el, st); }
        if (t.text === st.text) return;
        st.text = t.text; st.speaker = t.speaker;
        record(t.speaker, t.text);
        clearTimeout(st.timer);
        // Wait for the speaker to finish before treating it as a question.
        st.timer = setTimeout(function () {
          if (st.text === st.handled) return;
          st.handled = st.text;
          if (isSelf(st.speaker)) {
            // Your own speech is never answered as a question, but "stand-in, chart <topic>" shows a chart.
            if (NS.research && NS.research.handleSpeech(st.text)) return;
            if (NS.dataChart) NS.dataChart.handleSpeech(st.text);
            return;
          }
          // Anyone can ask the stand-in to research something and get back in the chat.
          if (NS.research && NS.research.handleSpeech(st.text)) return;
          fire(st.speaker, st.text);
        }, NS.config.captionDebounceMs);
      });
      return;
    }
    // Fallback: no turn structure found, read the region as one block.
    const el = regionEl();
    if (!el) return;
    const text = cleanText(el);
    if (!text || text === blockLast) return;
    blockLast = text;
    record('', text);
    clearTimeout(blockTimer);
    blockTimer = setTimeout(function () {
      // No speaker names in this layout, so a chart phrase is accepted from anyone in the caption box.
      if (NS.research && NS.research.handleSpeech(text)) return;
      if (NS.dataChart && NS.dataChart.handleSpeech(text)) return;
      fire('', text);
    }, NS.config.captionDebounceMs);
  }

  NS.captions = {
    start: function () {
      if (observer) return;
      // Whatever was said before now or while paused is not answered.
      turns.clear();
      items().forEach(function (el) {
        const t = readTurn(el);
        if (t) turns.set(el, { speaker: t.speaker, text: t.text, handled: t.text, timer: null });
      });
      const r = regionEl();
      blockLast = r && !items().length ? cleanText(r) : '';
      if (!NS.transcript.length) startedAt = Date.now();
      observer = new MutationObserver(scan);
      observer.observe(document.documentElement, { childList: true, subtree: true, characterData: true });
      NS.log('listening to captions');
    },
    stop: function () {
      if (observer) observer.disconnect();
      observer = null;
      clearTimeout(blockTimer);
      turns.forEach(function (st) { clearTimeout(st.timer); });
    },
  };
})();

// Camera slides: what the other people see instead of your face. One big sentence, an optional chart, a short slideshow.
// Drawn on a canvas and sent as the camera. Always labelled as an AI stand-in. No face, no voice.
(function () {
  const NS = (window.__standin = window.__standin || {});
  const W = 1280, H = 720;
  const PAL = ['#2f6fe4', '#e0782a', '#2a9d6f', '#a74fd0', '#c9a227', '#d6455d'];
  let canvas = null, ctx = null, stream = null, timer = null, hideTimer = null;
  const S = { frames: [], i: 0, since: 0, mode: 'idle', shown: 0, step: 0 };

  function init() {
    if (canvas) return;
    canvas = document.createElement('canvas');
    canvas.width = W; canvas.height = H;
    ctx = canvas.getContext('2d');
    draw();
    timer = setInterval(draw, 100);
    stream = canvas.captureStream(10);
  }

  function wrap(text, maxW, font) {
    ctx.font = font;
    const words = String(text).split(' '), lines = [];
    let cur = '';
    words.forEach(function (w) {
      const t = cur ? cur + ' ' + w : w;
      if (ctx.measureText(t).width > maxW && cur) { lines.push(cur); cur = w; } else cur = t;
    });
    if (cur) lines.push(cur);
    return lines;
  }
  // Biggest font (from 96 down to 32) at which the text fits in maxH pixels of height.
  function fit(text, maxW, maxH) {
    for (let px = 96; px >= 32; px -= 4) {
      const f = '700 ' + px + 'px system-ui, Segoe UI, sans-serif';
      const l = wrap(text, maxW, f);
      if (l.length * px * 1.2 <= maxH) return { px: px, font: f, lines: l };
    }
    const f = '700 32px system-ui, Segoe UI, sans-serif';
    return { px: 32, font: f, lines: wrap(text, maxW, f).slice(0, Math.floor(maxH / 38)) };
  }


  // Round axis values (1, 2, 5 times a power of ten) so the grid reads as 0, 5, 10, 15 and not 6.7, 11.4.
  function niceScale(lo, hi, n) {
    const raw = (hi - lo) / n, mag = Math.pow(10, Math.floor(Math.log10(raw))), f = raw / mag;
    const step = (f < 1.5 ? 1 : f < 3 ? 2 : f < 7 ? 5 : 10) * mag;
    return { lo: Math.floor(lo / step + 1e-9) * step, hi: Math.ceil(hi / step - 1e-9) * step, step: step };
  }
  // 1,400,000,000 -> "1.4B"; 12,500 -> "12.5K"; small numbers keep their decimals.
  function short(v, dec) {
    const a = Math.abs(v), t = function (x, u) { return String(Math.round(x * 100) / 100) + u; };
    if (a >= 1e9) return t(v / 1e9, 'B');
    if (a >= 1e6) return t(v / 1e6, 'M');
    if (a >= 1e4) return t(v / 1e3, 'K');
    return dec == null ? String(Math.round(v * 100) / 100) : v.toFixed(dec);
  }
  NS.shortNumber = short;

  // Line chart for a time series: one to three series, shared x labels (years), unit on the right of the legend row.
  function drawLine(c, x, y, w, h) {
    const series = c.series || [];
    const labels = [];
    series.forEach(function (s) { s.points.forEach(function (p) { if (labels.indexOf(p.label) < 0) labels.push(p.label); }); });
    labels.sort();
    let lo = Infinity, hi = -Infinity;
    series.forEach(function (s) { s.points.forEach(function (p) { lo = Math.min(lo, p.value); hi = Math.max(hi, p.value); }); });
    if (!isFinite(lo)) return;
    if (lo > 0 && hi / lo > 3) lo = 0;
    if (hi === lo) { hi += 1; lo -= 1; }
    const sc = niceScale(lo, hi, 4);
    lo = sc.lo; hi = sc.hi;
    const dec = sc.step >= 1 ? 0 : Math.min(3, Math.ceil(-Math.log10(sc.step)));
    const left = x + 120, right = x + w - 110, top = y + 40, bottom = y + h - 50;
    const px = function (label) { return labels.length < 2 ? (left + right) / 2 : left + (right - left) * labels.indexOf(label) / (labels.length - 1); };
    const py = function (v) { return bottom - (bottom - top) * (v - lo) / (hi - lo); };
    ctx.textBaseline = 'middle';
    ctx.font = '600 26px system-ui, sans-serif';
    for (let v = lo; v <= hi + sc.step / 2; v += sc.step) {
      const gy = py(v);
      ctx.strokeStyle = '#c9d0da'; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(left, gy); ctx.lineTo(right, gy); ctx.stroke();
      ctx.fillStyle = '#5a6472'; ctx.textAlign = 'right';
      ctx.fillText(short(v, dec), left - 12, gy);
    }
    // x labels: about 8 of them, always the last one; skip a label that would sit next to the last.
    const every = Math.max(1, Math.ceil(labels.length / 8));
    ctx.textAlign = 'center'; ctx.fillStyle = '#5a6472';
    labels.forEach(function (l, k) {
      const last = k === labels.length - 1;
      if (last || (k % every === 0 && labels.length - 1 - k >= every)) ctx.fillText(l, px(l), bottom + 28);
    });
    series.forEach(function (s, k) {
      const col = PAL[k % PAL.length];
      const pts = s.points.slice().sort(function (a, b) { return a.label < b.label ? -1 : 1; });
      ctx.strokeStyle = col; ctx.lineWidth = 6; ctx.lineJoin = 'round'; ctx.beginPath();
      pts.forEach(function (p, i) { if (i) ctx.lineTo(px(p.label), py(p.value)); else ctx.moveTo(px(p.label), py(p.value)); });
      ctx.stroke();
      ctx.fillStyle = col;
      pts.forEach(function (p) { ctx.beginPath(); ctx.arc(px(p.label), py(p.value), 7, 0, Math.PI * 2); ctx.fill(); });
      const lp = pts[pts.length - 1];
      ctx.textAlign = 'left'; ctx.font = '700 28px system-ui, sans-serif';
      ctx.fillText(short(lp.value), px(lp.label) + 14, py(lp.value));
      ctx.font = '600 26px system-ui, sans-serif';
    });
    if (series.length > 1 || c.unit) {
      ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
      let lx = left;
      if (series.length > 1) series.forEach(function (s, k) {
        ctx.fillStyle = PAL[k % PAL.length]; ctx.fillRect(lx, y + 4, 24, 24);
        ctx.fillStyle = '#14181f'; ctx.font = '600 26px system-ui, sans-serif';
        ctx.fillText(s.name, lx + 34, y + 16);
        lx += 34 + ctx.measureText(s.name).width + 36;
      });
      if (c.unit) { ctx.textAlign = 'right'; ctx.fillStyle = '#5a6472'; ctx.font = '600 26px system-ui, sans-serif'; ctx.fillText(c.unit, x + w, y + 16); }
    }
  }

  function drawChart(c, x, y, w, h) {
    if (c.type === 'line') return drawLine(c, x, y, w, h);
    const total = c.items.reduce(function (a, i) { return a + i.value; }, 0) || 1;
    if (c.type === 'pie') {
      const r = Math.min(h, w * 0.5) / 2 - 10, cx = x + r + 10, cy = y + h / 2;
      let a0 = -Math.PI / 2;
      c.items.forEach(function (it, k) {
        const a1 = a0 + (it.value / total) * Math.PI * 2;
        ctx.beginPath(); ctx.moveTo(cx, cy); ctx.arc(cx, cy, r, a0, a1); ctx.closePath();
        ctx.fillStyle = PAL[k % PAL.length]; ctx.fill();
        a0 = a1;
      });
      ctx.textBaseline = 'middle';
      c.items.forEach(function (it, k) {
        const ly = y + 30 + k * 56;
        ctx.fillStyle = PAL[k % PAL.length]; ctx.fillRect(x + r * 2 + 50, ly - 14, 28, 28);
        ctx.fillStyle = '#14181f'; ctx.font = '600 32px system-ui, sans-serif'; ctx.textAlign = 'left';
        ctx.fillText(it.label + '  ' + Math.round((it.value / total) * 100) + '%', x + r * 2 + 92, ly);
      });
    } else {
      const max = Math.max.apply(null, c.items.map(function (i) { return i.value; })) || 1;
      const rowH = Math.min(70, h / c.items.length);
      ctx.textBaseline = 'middle';
      c.items.forEach(function (it, k) {
        const ry = y + k * rowH + rowH / 2, bx = x + 300, bw = (w - 420) * (it.value / max);
        ctx.fillStyle = '#14181f'; ctx.font = '600 30px system-ui, sans-serif'; ctx.textAlign = 'right';
        ctx.fillText(it.label, bx - 16, ry);
        ctx.fillStyle = PAL[k % PAL.length]; ctx.fillRect(bx, ry - rowH * 0.3, Math.max(4, bw), rowH * 0.6);
        ctx.textAlign = 'left'; ctx.fillStyle = '#14181f';
        ctx.fillText(String(it.value), bx + Math.max(4, bw) + 12, ry);
      });
    }
  }

  function drawFrame(f) {
    ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, W, H);
    ctx.fillStyle = '#1f5fd1'; ctx.fillRect(0, 0, W, 14);
    ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
    if (f.kind === 'chart') {
      ctx.fillStyle = '#14181f'; ctx.font = '700 52px system-ui, sans-serif';
      ctx.fillText(String(f.chart.title || f.title || '').slice(0, 52), 70, 110);
      drawChart(f.chart, 70, 150, W - 140, f.chart.source ? 430 : 480);
      if (f.chart.source) {
        ctx.fillStyle = '#5a6472'; ctx.font = '600 24px system-ui, sans-serif'; ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
        ctx.fillText(String(f.chart.source).slice(0, 95), 70, H - 90);
      }
    } else {
      let y = 130;
      if (f.title) {
        ctx.fillStyle = '#1f5fd1'; ctx.font = '700 44px system-ui, sans-serif';
        ctx.fillText(f.title, 70, y); y += 70;
      }
      const t = fit(f.text, W - 140, f.title ? 400 : 500);
      ctx.fillStyle = '#14181f'; ctx.font = t.font;
      const block = t.lines.length * t.px * 1.2;
      let ty = f.title ? y + t.px * 0.9 : (H - 74 - block) / 2 + t.px * 0.85;
      t.lines.forEach(function (l) { ctx.fillText(l, 70, ty); ty += t.px * 1.2; });
    }
    // Footer label, always.
    ctx.fillStyle = '#eef2f8'; ctx.fillRect(0, H - 74, W, 74);
    ctx.fillStyle = '#14181f'; ctx.font = '600 30px system-ui, sans-serif'; ctx.textBaseline = 'middle';
    ctx.fillText('AI stand-in for ' + NS.config.userName, 70, H - 37);
    if (S.frames.length > 1) {
      ctx.textAlign = 'right';
      ctx.fillText((S.i + 1) + ' / ' + S.frames.length, W - 70, H - 37);
    }
    ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  }

  function draw() {
    if (!ctx) return;
    const step = S.step || NS.config.slideStepMs || 5000;
    if (S.mode === 'show' && S.frames.length > 1 && S.i < S.frames.length - 1 && Date.now() - S.since >= step) {
      S.i++; S.since = Date.now();
    }
    const idle = { kind: 'text', title: '', text: 'AI stand-in for ' + NS.config.userName + ' \u2013 listening' };
    const f = S.mode === 'show' ? S.frames[S.i] : idle;
    drawFrame(f);
  }

  function framesFor(result, text) {
    const o = result && result.open;
    if (o) {
      const fr = o.slides.map(function (s) { return { kind: 'text', title: s.title, text: s.text }; });
      if (o.chart) fr.push({ kind: 'chart', chart: o.chart });
      return fr;
    }
    const clean = String(text || '').replace(/^I am an AI stand-in for [^.]*\.\s*/, '');
    return [{ kind: 'text', title: '', text: clean }];
  }

  NS.slides = {
    init: init,
    stream: function () { init(); return stream; },
    show: function (result, text) {
      init();
      S.frames = framesFor(result, text);
      S.i = 0; S.since = Date.now(); S.mode = 'show'; S.shown++; S.step = 0;
      const total = (NS.config.slideStepMs || 5000) * (S.frames.length - 1) + (NS.config.slideHoldMs || 9000);
      clearTimeout(hideTimer);
      hideTimer = setTimeout(function () { S.mode = 'idle'; }, total);
      draw();
      NS.log('camera slide: ' + S.frames.length + ' frame(s)');
    },
    // Show ready-made frames (used by the data chart). opts: { stepMs, holdMs }
    showFrames: function (frames, opts) {
      init();
      opts = opts || {};
      S.frames = frames; S.i = 0; S.since = Date.now(); S.mode = 'show'; S.shown++; S.step = opts.stepMs || 0;
      const step = opts.stepMs || NS.config.slideStepMs || 5000;
      const total = step * (frames.length - 1) + (opts.holdMs || NS.config.slideHoldMs || 9000);
      clearTimeout(hideTimer);
      hideTimer = setTimeout(function () { S.mode = 'idle'; }, total);
      draw();
      NS.log('camera frames: ' + frames.length);
    },
    clear: function () { clearTimeout(hideTimer); S.mode = 'idle'; draw(); },
    state: function () { return { mode: S.mode, i: S.i, frames: S.frames.length, shown: S.shown }; },
    canvas: function () { init(); return canvas; },
  };
})();

// Camera only: Meet gets the slide canvas as your camera. Your real microphone is left alone. No voice from the stand-in.
(function () {
  const NS = (window.__standin = window.__standin || {});
  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) return;
  const real = navigator.mediaDevices.getUserMedia.bind(navigator.mediaDevices);
  NS.cameraCalls = 0;
  navigator.mediaDevices.getUserMedia = async function (constraints) {
    const wantsVideo = !!(constraints && constraints.video);
    if (!NS.config.camera || !wantsVideo) return real(constraints);
    NS.cameraCalls++;
    const tracks = [];
    if (constraints.audio) {
      try { (await real({ audio: constraints.audio })).getAudioTracks().forEach(function (t) { tracks.push(t); }); } catch (e) { NS.log('real mic not available: ' + e.message); }
    }
    NS.slides.stream().getVideoTracks().forEach(function (t) { tracks.push(t.clone()); });
    NS.log('gave Meet the slide camera (audio=' + !!constraints.audio + ')');
    return new MediaStream(tracks);
  };
})();

// Posts the stand-in's answer into the Google Meet chat. No face, no voice.
// NOTE: Meet's page layout can change without warning. This finds the chat box by its label.
(function () {
  const NS = (window.__standin = window.__standin || {});
  const sleep = function (ms) { return new Promise(function (r) { setTimeout(r, ms); }); };
  const visible = function (el) { return !!(el && (el.offsetWidth || el.offsetHeight || el.getClientRects().length)); };
  const label = function (el) { return (el.getAttribute('aria-label') || '') + ' ' + (el.getAttribute('placeholder') || ''); };

  function findInput() {
    return Array.prototype.find.call(document.querySelectorAll('textarea, [contenteditable="true"], input[type="text"]'), function (el) {
      return visible(el) && /message/i.test(label(el));
    });
  }
  function findChatButton() {
    return Array.prototype.find.call(document.querySelectorAll('button, [role="button"]'), function (b) {
      return /^chat with everyone/i.test(b.getAttribute('aria-label') || '');
    });
  }
  function findSend() {
    return Array.prototype.find.call(document.querySelectorAll('button, [role="button"]'), function (b) {
      return visible(b) && /^send/i.test(b.getAttribute('aria-label') || '') && b.tagName === 'BUTTON';
    });
  }
  function setValue(el, text) {
    el.focus();
    if (el.isContentEditable) {
      document.execCommand('selectAll', false);
      document.execCommand('insertText', false, text);
      return;
    }
    const proto = el.tagName === 'TEXTAREA' ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
    Object.getOwnPropertyDescriptor(proto, 'value').set.call(el, text);
    el.dispatchEvent(new Event('input', { bubbles: true }));
  }
  function pressEnter(el) {
    ['keydown', 'keypress', 'keyup'].forEach(function (t) {
      el.dispatchEvent(new KeyboardEvent(t, { key: 'Enter', code: 'Enter', keyCode: 13, which: 13, bubbles: true }));
    });
  }
  async function ensureOpen() {
    let input = findInput();
    if (input) return input;
    const btn = findChatButton();
    if (btn) btn.click();
    for (let i = 0; i < 30; i++) {
      await sleep(100);
      input = findInput();
      if (input) return input;
    }
    throw new Error('Meet chat box not found. Open the chat panel once and try again.');
  }

  const sent = [];
  NS.chat = {
    sent: sent,
    // Always labelled, so nobody mistakes it for the person.
    prefix: function () { return '[AI stand-in for ' + NS.config.userName + '] '; },
    post: async function (text) {
      const line = NS.chat.prefix() + text;
      const input = await ensureOpen();
      setValue(input, line);
      await sleep(80);
      const send = findSend();
      if (send && !send.disabled) send.click();
      else pressEnter(input);
      await sleep(150);
      sent.push(line);
      NS.log('posted to chat: ' + line);
    },
    // Quick self-check: can the stand-in find the Meet chat?
    check: function () { return { chatBox: !!findInput(), chatButton: !!findChatButton() }; },
  };
})();

// Data chart: say "stand-in, chart India GDP growth" and the camera shows a chart of public data, with its source.
//
// How it works (all steps are logged with a timestamp and step n/5):
//   1 plan   the model picks where to look (World Bank indicator, or a Wikipedia search). It only chooses WHERE; it never supplies numbers.
//   2 fetch  the relay downloads the data (only api.worldbank.org and en.wikipedia.org are allowed there).
//   3 build  numbers are read from the download and checked. For Wikipedia, every number must appear word for word in the page.
//   4 show   the chart goes on the camera, with its source written on the slide, then a one-line summary worked out from the numbers.
//   5 chat   one labelled line with the source goes in the Meet chat.
// Nothing is charted unless real data was found. Numbers never come from the model's memory.
(function () {
  const NS = (window.__standin = window.__standin || {});
  const STEPS = 5;
  const HOSTS = ['api.worldbank.org', 'en.wikipedia.org'];

  function cut(x, n) { return String(x == null ? '' : x).replace(/\s+/g, ' ').trim().slice(0, n); }
  function esc(s) { return encodeURIComponent(s); }

  // ---- Trigger phrase ----------------------------------------------------------------------------------------------
  // "stand-in, chart <topic>"  or  "Eswar, show the data on <topic>"  (also: plot, graph). Only your own speech counts.
  // Meet's captions often mishear "stand-in" ("You?", "Stand.", "standing"), so several spellings count, and so does a bare "Chart <topic>"
  // at the start of a sentence (only your own speech is checked, so this is safe enough).
  function aliases() {
    const name = String(NS.config.userName || 'Eswar').replace(/[^A-Za-z]/g, '');
    return ['stand[\\s-]?in', 'standing', 'stand', 'you', 'hey', 'ishwar', 'eshwar', 'eswar', 'iswar', 'ishwara', 'eswara', name].filter(Boolean).join('|');
  }
  function triggerRe() {
    return new RegExp('\\b(?:' + aliases() + ')\\b[?,:.\\s-]*(?:please\\s+)?(?:show|chart|plot|graph)\\b[\\s,]*(?:(?:me|us|the|a|data|numbers|chart|graph|on|for|about|of)\\b[\\s,]*)*([^.?!\\n]{4,160})', 'gi');
  }
  function bareRe() {
    return /(?:^|[.?!]\s+)(?:please\s+)?(?:chart|plot|graph)\s+(?!(?:shows?|is|was|here|above|below|on|looks?|where|that|which|this|these|those|it|there)\b)((?:the |a |me |us |data |on |for |about |of )*[^.?!\n]{4,160})/gi;
  }
  function detect(text) {
    const t = String(text || '');
    let m, last = '', lastAt = -1;
    const re = triggerRe();
    while ((m = re.exec(t))) { last = m[1]; lastAt = m.index; }
    const re2 = bareRe();
    while ((m = re2.exec(t))) { if (m.index >= lastAt) { last = m[1]; lastAt = m.index; } }
    return cut(last, 160).replace(/[,;:\s]+$/, '');
  }

  // ---- Plan ----------------------------------------------------------------------------------------------------------
  const YEAR = function () { return new Date().getFullYear(); };
  function buildPlanPrompt(topic) {
    return {
      system:
        'You choose where to find public data for a chart that a speaker asked for. You do not provide any numbers. Reply with JSON only.\n' +
        'Option 1, for country-level economic, social, demographic or environmental statistics: ' +
        '{"source":"worldbank","indicator":"<World Bank indicator code, for example NY.GDP.MKTP.KD.ZG>","countries":["IND"],"from":2015,"to":2024,"title":"<at most 8 words>"}. ' +
        'Use ISO3 country codes (WLD for the world), at most 3 countries, at most 25 years, and end at least one year before today.\n' +
        'Option 2, for anything else (a Wikipedia article will be searched and read): {"source":"wikipedia","query":"<search words, at most 8>","title":"<at most 8 words>"}.',
      user: 'Today\'s year: ' + YEAR() + '\nRequest: ' + topic,
    };
  }
  function parsePlan(text, topic) {
    const fallback = { source: 'wikipedia', query: cut(topic, 100).replace(/[^\w\s'-]/g, ' '), title: cut(topic, 60) };
    const m = String(text || '').match(/\{[\s\S]*\}/);
    if (!m) return fallback;
    let o;
    try { o = JSON.parse(m[0]); } catch (e) { return fallback; }
    const title = cut(o.title || topic, 60);
    if (o.source === 'worldbank') {
      const ind = String(o.indicator || '').trim();
      const countries = Array.from(new Set((Array.isArray(o.countries) ? o.countries : []).map(function (c) { return String(c).trim().toUpperCase(); })));
      const from = Math.round(Number(o.from)), to = Math.round(Number(o.to));
      const okInd = /^[A-Za-z0-9]{2,12}(\.[A-Za-z0-9_]{1,12}){1,4}$/.test(ind);
      const okC = countries.length >= 1 && countries.length <= 3 && countries.every(function (c) { return /^[A-Z]{3}$/.test(c); });
      const okY = isFinite(from) && isFinite(to) && from >= 1960 && to <= YEAR() && to >= from && to - from <= 40;
      if (okInd && okC && okY) return { source: 'worldbank', indicator: ind, countries: countries, from: from, to: to, title: title };
      return fallback;
    }
    if (o.source === 'wikipedia') {
      const q = cut(o.query, 100).replace(/[^\w\s'-]/g, ' ').replace(/\s+/g, ' ').trim();
      return q.length >= 3 ? { source: 'wikipedia', query: q, title: title } : fallback;
    }
    return fallback;
  }

  // ---- Relay helpers -------------------------------------------------------------------------------------------------
  async function llmJson(system, user) {
    const d = await NS.relayCall('llm', { system: system, user: user, maxTokens: 900 }, 30000);
    return (d.json && d.json.text) || '';
  }
  async function fetchPublic(url) {
    const host = new URL(url).hostname;
    if (HOSTS.indexOf(host) < 0) throw new Error('host not allowed: ' + host);
    const d = await NS.relayCall('fetch', { url: url }, 30000);
    if (!d.json || d.json.status !== 200 || typeof d.json.body !== 'string') throw new Error('fetch failed (' + (d.json && d.json.status) + ')');
    return d.json.body;
  }

  // ---- World Bank ----------------------------------------------------------------------------------------------------
  function worldBankUrl(p) {
    return 'https://api.worldbank.org/v2/country/' + p.countries.join(';') + '/indicator/' + p.indicator + '?format=json&per_page=400&date=' + p.from + ':' + p.to;
  }
  // Returns a chart or null. Rows look like { date:"2023", value:8.2, country:{value:"India"}, indicator:{value:"GDP growth (annual %)"} }.
  function parseWorldBank(body, plan) {
    let j;
    try { j = JSON.parse(body); } catch (e) { return null; }
    if (!Array.isArray(j) || j.length < 2 || !Array.isArray(j[1])) return null;
    const by = {};
    let indName = '';
    j[1].forEach(function (r) {
      if (r == null || r.value == null || !isFinite(Number(r.value))) return;
      const name = cut(r.country && r.country.value, 40) || cut(r.countryiso3code, 3);
      indName = indName || cut(r.indicator && r.indicator.value, 120);
      (by[name] = by[name] || []).push({ label: String(r.date), value: Math.round(Number(r.value) * 1000) / 1000 });
    });
    const series = Object.keys(by).map(function (k) { return { name: k, points: by[k].sort(function (a, b) { return a.label < b.label ? -1 : 1; }) }; })
      .filter(function (s) { return s.points.length >= NS.config.chartMinPoints; });
    if (!series.length) return null;
    const labels = [].concat.apply([], series.map(function (s) { return s.points.map(function (p) { return p.label; }); })).sort();
    const unit = (indName.match(/\(([^()]*)\)\s*$/) || [])[1] || '';
    return {
      type: 'line', title: plan.title, unit: cut(unit, 30), series: series,
      source: 'Source: World Bank, ' + plan.indicator + ', ' + labels[0] + '-' + labels[labels.length - 1],
      sourceName: 'World Bank (' + plan.indicator + ', ' + (indName || 'indicator') + ')',
    };
  }

  // ---- Wikipedia (fallback) ------------------------------------------------------------------------------------------
  function htmlToText(html) {
    return String(html || '')
      .replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ')
      .replace(/<sup[\s\S]*?<\/sup>/gi, '')
      .replace(/<\/(tr|p|li|h[1-6]|caption)>/gi, '\n')
      .replace(/<\/t[dh]>/gi, ' | ')
      .replace(/<[^>]+>/g, '')
      .replace(/&nbsp;|&#160;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#0?39;/g, "'")
      .replace(/&#\d+;|&[a-z]+;/g, ' ')
      .replace(/[ \t]+/g, ' ').replace(/ ?\| ?\n/g, '\n').replace(/\n{2,}/g, '\n').trim();
  }
  function norm(t) { return String(t || '').replace(/[\s\u00a0]+/g, ' ').trim().toLowerCase(); }
  function numbersIn(s) {
    return (String(s).replace(/(\d),(?=\d{3}\b)/g, '$1').match(/-?\d+(?:\.\d+)?/g) || []).map(Number);
  }
  // Every point must come with the exact words from the page that contain its number. Any miss rejects the whole chart.
  function validateExtract(o, pageText, minPoints) {
    if (!o || !Array.isArray(o.points)) return { ok: false, reason: 'no points' };
    const hay = norm(pageText);
    const pts = o.points.slice(0, 12);
    if (pts.length < minPoints) return { ok: false, reason: 'too few points (' + pts.length + ')' };
    const out = [];
    for (let i = 0; i < pts.length; i++) {
      const p = pts[i], v = Number(p && p.value), q = norm(p && p.quote);
      const label = cut(p && p.label, 30);
      if (!label || !isFinite(v) || q.length < 6) return { ok: false, reason: 'point ' + (i + 1) + ' is incomplete' };
      if (hay.indexOf(q) < 0) return { ok: false, reason: 'point ' + (i + 1) + ': quote not found in the page' };
      if (!numbersIn(q).some(function (n) { return Math.abs(n - v) < 1e-9; })) return { ok: false, reason: 'point ' + (i + 1) + ': number not in its quote' };
      out.push({ label: label, value: v });
    }
    return { ok: true, points: out };
  }
  function buildPrompt(topic, pageText) {
    return {
      system:
        'Extract ONE numeric series from the page text that best answers the request: a time series (labels are years or dates) or a ranking of up to 8 items. ' +
        'Use ONLY numbers that appear in the text. Do not calculate, estimate or convert anything. ' +
        'Reply with JSON only: {"title":"<at most 8 words>","unit":"<unit, may be empty>","points":[{"label":"2019","value":12.5,"quote":"the exact words copied from the text that contain this number"}]}. ' +
        '3 to 12 points. If the text has no suitable numbers, reply {"points":[]}.',
      user: 'Request: ' + topic + '\n\nPage text:\n' + pageText.slice(0, 12000),
    };
  }
  // Search Wikipedia, read the best page as plain text (tables kept as "a | b" rows). Null if there is no usable page.
  async function wikiPage(query) {
    const sBody = await fetchPublic('https://en.wikipedia.org/w/api.php?action=query&list=search&srlimit=3&format=json&srsearch=' + esc(query));
    let hits;
    try { hits = JSON.parse(sBody).query.search; } catch (e) { hits = []; }
    if (!hits || !hits.length) return null;
    const title = hits[0].title;
    const pBody = await fetchPublic('https://en.wikipedia.org/w/api.php?action=parse&prop=text&redirects=1&format=json&page=' + esc(title));
    let html;
    try { html = JSON.parse(pBody).parse.text['*']; } catch (e) { return null; }
    return { title: title, url: 'https://en.wikipedia.org/wiki/' + esc(title.replace(/ /g, '_')), text: htmlToText(html) };
  }
  async function fromWikipedia(plan, topic) {
    const pg = await wikiPage(plan.query);
    if (!pg) return { ok: false, reason: 'no usable Wikipedia page found' };
    const title = pg.title, text = pg.text, url = pg.url;
    const pr = buildPrompt(topic, text);
    const raw = await llmJson(pr.system, pr.user);
    const m = String(raw).match(/\{[\s\S]*\}/);
    let o = null;
    try { o = m ? JSON.parse(m[0]) : null; } catch (e) { o = null; }
    const v = validateExtract(o, text, NS.config.chartMinPoints);
    if (!v.ok) return { ok: false, reason: 'Wikipedia "' + title + '": ' + v.reason };
    const years = v.points.every(function (p) { return /^\d{4}/.test(p.label); });
    const ctitle = cut(o.title || plan.title, 60);
    const base = { title: ctitle, unit: cut(o.unit, 30), source: 'Source: Wikipedia, ' + title, sourceName: 'Wikipedia, "' + title + '" (' + url + ')' };
    const chart = years
      ? Object.assign(base, { type: 'line', series: [{ name: ctitle, points: v.points }] })
      : Object.assign(base, { type: 'bar', items: v.points.slice(0, 8) });
    return { ok: true, chart: chart };
  }

  // ---- Summary worked out from the numbers (never written by the model) ----------------------------------------------
  function r(n) { return NS.shortNumber ? NS.shortNumber(n) : String(Math.round(n * 100) / 100); }
  function summarise(c) {
    if (c.type === 'bar') {
      const s = c.items.slice().sort(function (a, b) { return b.value - a.value; });
      return 'Highest: ' + s[0].label + ' (' + r(s[0].value) + '). Lowest: ' + s[s.length - 1].label + ' (' + r(s[s.length - 1].value) + ').';
    }
    if (c.series.length === 1) {
      const p = c.series[0].points, hi = p.reduce(function (a, b) { return b.value > a.value ? b : a; });
      const f = p[0], l = p[p.length - 1], d = l.value - f.value;
      return 'Peak: ' + r(hi.value) + ' in ' + hi.label + '. Latest: ' + r(l.value) + ' in ' + l.label + ', ' + (d >= 0 ? 'up ' : 'down ') + r(Math.abs(d)) + ' since ' + f.label + '.';
    }
    return c.series.map(function (s) {
      const f = s.points[0], l = s.points[s.points.length - 1], d = l.value - f.value;
      return s.name + ' ' + (d >= 0 ? 'up ' : 'down ') + r(Math.abs(d)) + ' (' + f.label + ' to ' + l.label + ')';
    }).join('. ') + '.';
  }

  // ---- Run -----------------------------------------------------------------------------------------------------------
  let running = false;
  const seen = {}; // topic -> time last charted from speech
  const msg = function (title, text) { return [{ kind: 'text', title: title, text: text }]; };

  async function run(topic) {
    topic = cut(topic, 160);
    if (!topic) return { ok: false, reason: 'no topic' };
    if (running) { NS.log('data chart: busy, ignored "' + topic + '"'); return { ok: false, reason: 'busy' }; }
    running = true;
    const t0 = performance.now();
    const step = function (n, what) { NS.log('data chart: ' + what, n, STEPS); };
    try {
      NS.slides.showFrames(msg('Looking up public data', topic), { holdMs: 25000 });
      if (!(await NS.relayReady())) {
        NS.log('data chart: relay not found, cannot look up data. Press Connect relay in the panel.');
        NS.slides.showFrames(msg('Data lookup is off', 'The relay is not running.'), { holdMs: 5000 });
        return { ok: false, reason: 'relay not running' };
      }
      step(1, 'planning where to look for "' + topic + '"');
      const pr = buildPlanPrompt(topic);
      const plan = parsePlan(await llmJson(pr.system, pr.user), topic);
      step(2, 'plan: ' + (plan.source === 'worldbank' ? 'World Bank ' + plan.indicator + ' ' + plan.countries.join(',') + ' ' + plan.from + '-' + plan.to : 'Wikipedia search "' + plan.query + '"'));
      let chart = null, why = '';
      if (plan.source === 'worldbank') {
        try { chart = parseWorldBank(await fetchPublic(worldBankUrl(plan)), plan); } catch (e) { why = 'World Bank: ' + e.message; }
        if (!chart && !why) why = 'World Bank returned no usable data for ' + plan.indicator;
        if (!chart) {
          NS.log('data chart: ' + why + '; trying Wikipedia');
          plan.source = 'wikipedia'; plan.query = cut(topic, 100).replace(/[^\w\s'-]/g, ' ');
        }
      }
      if (!chart) {
        try {
          const w = await fromWikipedia(plan, topic);
          if (w.ok) chart = w.chart; else why = (why ? why + '; ' : '') + w.reason;
        } catch (e) { why = (why ? why + '; ' : '') + 'Wikipedia: ' + e.message; }
      }
      step(3, chart ? 'data checked: ' + (chart.series ? chart.series.map(function (s) { return s.name + ' ' + s.points.length + ' points'; }).join(', ') : chart.items.length + ' items') : 'no reliable data (' + why + ')');
      if (!chart) {
        NS.slides.showFrames(msg('No reliable data found', topic), { holdMs: 6000 });
        return { ok: false, reason: why || 'no data' };
      }
      const frames = [{ kind: 'chart', chart: chart }, { kind: 'text', title: 'What the data shows', text: summarise(chart) }];
      NS.slides.showFrames(frames, { stepMs: NS.config.chartStepMs, holdMs: NS.config.chartHoldMs });
      step(4, 'chart on the camera in ' + Math.round(performance.now() - t0) + ' ms');
      if (NS.config.chartChat && NS.chat) {
        try { await NS.chat.post('Chart on screen: ' + cut(chart.title, 60) + '. ' + chart.sourceName + '. ' + summarise(chart)); } catch (e) { NS.log('data chart: chat post failed: ' + e.message); }
      }
      step(5, 'done');
      const res = { ok: true, topic: topic, chart: chart, summary: summarise(chart), ms: Math.round(performance.now() - t0), at: NS.isoLocal() };
      NS.chartHistory.unshift(res);
      NS.events.dispatchEvent(new CustomEvent('chart', { detail: res }));
      return res;
    } catch (e) {
      NS.log('data chart failed: ' + e.message);
      try { NS.slides.showFrames(msg('Data lookup failed', 'Try again.'), { holdMs: 4000 }); } catch (e2) { /* ignore */ }
      return { ok: false, reason: e.message };
    } finally {
      running = false;
    }
  }

  // Called by the caption reader with your own speech. Runs at most once per topic every few minutes.
  function handleSpeech(text) {
    if (!NS.config.dataChart) return false;
    const topic = detect(text);
    if (!topic) return false;
    const key = norm(topic), now = Date.now();
    if (seen[key] && now - seen[key] < (NS.config.chartRepeatMs || 300000)) return false;
    seen[key] = now;
    NS.log('heard a chart request: ' + topic);
    run(topic);
    return true;
  }

  NS.chartHistory = NS.chartHistory || [];
  NS.events = NS.events || new EventTarget();
  NS.dataChart = { aliases: aliases, llmJson: llmJson, fetchPublic: fetchPublic, wikiPage: wikiPage, norm: norm, numbersIn: numbersIn, cut: cut, detect: detect, run: run, handleSpeech: handleSpeech, parsePlan: parsePlan, parseWorldBank: parseWorldBank, validateExtract: validateExtract, htmlToText: htmlToText, summarise: summarise };
})();

// Research and get back: someone says "stand-in, research <topic> and get back to me" (or "Eswar, look into ...").
// Anyone in the meeting can ask. The stand-in answers in the Meet chat only (no camera change, no voice):
//   1 an immediate one-line acknowledgement,
//   2 it finds a Wikipedia page (through the relay's allowlist),
//   3 the model writes up to 4 sentences, each with the exact words from the page that support it,
//   4 a sentence is kept only if its quote is really in the page. Anything else is dropped,
//   5 one labelled chat message with the kept sentences and the source link. If nothing survives, it says it found nothing reliable.
(function () {
  const NS = (window.__standin = window.__standin || {});
  const seen = {};
  let running = false;

  function triggerRe() {
    return new RegExp('\\b(?:' + DC().aliases() + ')\\b[?,:.\\s-]*(?:can you |could you |please )*(?:do some research (?:on|about|into)|research|look into|look up|find out (?:about|more about)?|dig into)\\b[\\s,]*(?:(?:on|about|for|into|the|something|some)\\b[\\s,]*)*([^.?!\\n]{4,160})', 'i');
  }
  // Also "research <topic> and get back to me" with no name at all (the captions often drop the name).
  function bareRe() {
    return /(?:^|[.?!]\s+)(?:(?:can|could) you |please )*(?:do some research (?:on|about|into)|research|look into|look up|dig into)\s+((?:on |about |for |into |the |something |some )*[^.?!\n]{4,160}?)\s*(?:,?\s*(?:and|then)\s+)?(?:get|come) back to (?:me|us)\b/i;
  }
  function detect(text) {
    const t = String(text || '');
    const m = t.match(triggerRe()) || t.match(bareRe());
    if (!m) return '';
    return DC().cut(m[1].replace(/\b(?:and|then)?\s*(?:get|come) back to (?:me|us)\b.*$/i, '').replace(/\b(?:and|then)\s*(?:let|tell) (?:me|us) know\b.*$/i, ''), 160).replace(/[,;:\s]+$/, '').replace(/\s+please$/i, '');
  }
  function DC() { return NS.dataChart; }
  function step(n, t) { NS.log('research [' + n + '/5]: ' + t); }

  function prompt(topic, pageText) {
    return {
      system:
        'Write a short factual answer to the request using ONLY the page text. Up to 4 sentences. Do not add anything from memory. ' +
        'Every sentence must come with a quote: the exact words copied from the page text that support it. ' +
        'Reply with JSON only: {"sentences":[{"text":"<one sentence>","quote":"<exact words from the page, at least 6 characters>"}]}. ' +
        'If the page does not answer the request, reply {"sentences":[]}.',
      user: 'Request: ' + topic + '\n\nPage text:\n' + pageText.slice(0, 12000),
    };
  }
  // Keep only sentences whose quote is word for word in the page. Returns the kept sentences.
  function checkAnswer(o, pageText) {
    if (!o || !Array.isArray(o.sentences)) return [];
    const hay = DC().norm(pageText);
    const out = [];
    o.sentences.slice(0, 4).forEach(function (s) {
      const q = DC().norm(s && s.quote), t = DC().cut(s && s.text, 300);
      if (t && q.length >= 6 && hay.indexOf(q) >= 0) out.push(t);
    });
    return out;
  }

  async function run(topic) {
    if (running) { NS.log('research: already working on one request'); return { ok: false, reason: 'busy' }; }
    running = true;
    const t0 = performance.now();
    try {
      step(1, 'request: ' + topic);
      try { await NS.chat.post('Noted. I will look up "' + topic + '" and post what I find here shortly.'); } catch (e) { NS.log('research: chat post failed: ' + e.message); }
      if (NS.relayReady && !(await NS.relayReady())) {
        await NS.chat.post('I cannot reach my lookup service right now, so Eswar will follow up on "' + topic + '" himself.');
        return { ok: false, reason: 'relay not running' };
      }
      const pg = await DC().wikiPage(DC().cut(topic, 100).replace(/[^\w\s'-]/g, ' '));
      step(2, pg ? 'page: ' + pg.title : 'no page found');
      let kept = [];
      if (pg) {
        const p = prompt(topic, pg.text);
        const raw = await DC().llmJson(p.system, p.user);
        const m = String(raw).match(/\{[\s\S]*\}/);
        let o = null;
        try { o = m ? JSON.parse(m[0]) : null; } catch (e) { o = null; }
        step(3, 'model gave ' + ((o && o.sentences && o.sentences.length) || 0) + ' sentences');
        kept = checkAnswer(o, pg.text);
        step(4, kept.length + ' sentences kept after the quote check');
      }
      let msg;
      if (kept.length) msg = 'Research on "' + topic + '": ' + kept.join(' ') + ' Source: Wikipedia, "' + pg.title + '" (' + pg.url + '). Not checked by Eswar yet.';
      else msg = 'I looked for "' + topic + '" but found nothing reliable I can quote, so I will not guess. Eswar will follow up.';
      await NS.chat.post(msg);
      step(5, 'posted in ' + Math.round(performance.now() - t0) + ' ms');
      const res = { ok: kept.length > 0, topic: topic, kept: kept, source: pg && pg.url, at: NS.isoLocal() };
      NS.researchHistory.unshift(res);
      return res;
    } catch (e) {
      NS.log('research failed: ' + e.message);
      try { await NS.chat.post('My lookup on "' + topic + '" failed, so Eswar will follow up himself.'); } catch (e2) { /* ignore */ }
      return { ok: false, reason: e.message };
    } finally { running = false; }
  }

  function handleSpeech(text) {
    if (NS.config.research === false || !DC()) return false;
    const topic = detect(text);
    if (!topic) return false;
    const key = DC().norm(topic), now = Date.now();
    if (seen[key] && now - seen[key] < (NS.config.chartRepeatMs || 300000)) return true;
    seen[key] = now;
    NS.log('heard a research request: ' + topic);
    run(topic);
    return true;
  }
  NS.researchHistory = NS.researchHistory || [];
  NS.research = { detect: detect, run: run, handleSpeech: handleSpeech, checkAnswer: checkAnswer };
})();

// All-in-one stand-in: captions in -> answer in the Meet chat AND as slides on your camera. Control panel with Yes/No override.
(function () {
  const NS = (window.__standin = window.__standin || {});
  if (NS.started) { console.log('stand-in is already running'); return; }
  NS.started = true;
  NS.config.output = 'all';
  NS.config.realVoice = false;
  NS.config.override = true;
  NS.config.enabled = true;

  function el(tag, css, text) {
    const e = document.createElement(tag);
    if (css) e.style.cssText = css;
    if (text != null) e.textContent = text;
    return e;
  }
  const BTN = 'font:inherit;padding:4px 10px;border:1px solid #1f5fd1;background:#1f5fd1;color:#fff;border-radius:6px;cursor:pointer';
  let ui = null;
  function buildPanel() {
    if (ui || !document.body) return;
    const host = el('div', 'position:fixed;left:12px;bottom:12px;z-index:2147483647;font:14px/1.35 system-ui,sans-serif;background:#fff;color:#14181f;border:1px solid #d9dee6;border-radius:12px;padding:12px;width:300px;box-shadow:0 4px 16px rgba(0,0,0,.25)');
    host.id = 'standin-all-panel';
    const title = el('div', 'font-weight:700;font-size:16px', 'AI stand-in for ' + NS.config.userName);
    const status = el('div', 'color:#5a6472;font-size:12px;margin-top:2px');
    const row1 = el('div', 'display:flex;gap:8px;align-items:center;margin-top:8px');
    const toggle = el('button', BTN, 'Pause');
    toggle.id = 'standin-toggle';
    const relay = el('button', BTN, 'Connect relay');
    relay.id = 'standin-relay';
    row1.append(toggle, relay);
    const row2 = el('div', 'display:flex;gap:8px;align-items:center;margin-top:8px');
    const thr = el('input'); thr.type = 'range'; thr.min = '50'; thr.max = '95'; thr.step = '1'; thr.value = NS.config.threshold; thr.id = 'standin-thr';
    thr.setAttribute('aria-label', 'Answer at confidence'); thr.style.flex = '1';
    const thrv = el('span', '', NS.config.threshold + '%');
    row2.append(el('span', '', 'Answer at'), thr, thrv);
    const row3 = el('div', 'display:flex;gap:8px;margin-top:8px');
    const q = el('input', 'flex:1;min-width:0;padding:6px;border:1px solid #d9dee6;border-radius:6px'); q.type = 'text'; q.id = 'standin-q';
    q.placeholder = 'Test question or: stand-in, chart ...'; q.setAttribute('aria-label', 'Test question');
    const ask = el('button', BTN, 'Ask'); ask.id = 'standin-ask';
    row3.append(q, ask);
    const last = el('div', 'margin-top:8px;font-size:13px'); last.id = 'standin-last';
    const ovText = el('div', 'font-weight:700;color:#a35a00');
    const ovRow = el('div', 'display:flex;gap:8px;margin-top:6px');
    const yes = el('button', BTN, 'Yes'), no = el('button', BTN, 'No');
    yes.id = 'standin-yes'; no.id = 'standin-no';
    ovRow.append(yes, no);
    const ov = el('div', 'display:none;margin-top:8px;padding:8px;border:2px solid #a35a00;border-radius:8px'); ov.id = 'standin-override';
    ov.append(ovText, ovRow);
    const row4 = el('div', 'display:flex;gap:8px;align-items:center;margin-top:8px;flex-wrap:wrap');
    const save = el('button', BTN, 'Save captions (.md)'); save.id = 'standin-save';
    const saved = el('span', 'color:#5a6472;font-size:12px');
    const clear = el('button', BTN, 'Clear camera'); clear.id = 'standin-clear';
    row4.append(save, clear, saved);
    clear.onclick = function () { NS.slides.clear(); saved.textContent = 'Camera cleared.'; };
    save.onclick = function () { saved.textContent = NS.downloadTranscript() ? 'Saved.' : 'No captions yet.'; };
    host.append(title, status, row1, row2, row3, row4, ov, last);
    document.body.appendChild(host);
    ui = { status: status, toggle: toggle, last: last, ov: ov, ovText: ovText, relay: relay };

    toggle.onclick = function () { NS.listening ? window.standin.stop() : window.standin.start(); };
    relay.onclick = function () { last.textContent = NS.openBridge(true) ? 'Relay window opened. Leave it open.' : 'Pop-up blocked. Allow pop-ups for Meet and press again.'; };
    thr.oninput = function () { NS.config.threshold = Number(thr.value); thrv.textContent = thr.value + '%'; NS.saveConfig(); };
    ask.onclick = function () {
      const v = q.value.trim(); if (!v) return;
      // A chart phrase typed here, for example: stand-in, chart India GDP growth
      const rtopic = NS.research && NS.research.detect(v);
      if (rtopic) { last.textContent = 'Researching: ' + rtopic + ' (answer goes to the chat)'; NS.research.run(rtopic); return; }
      const topic = NS.dataChart.detect(v);
      if (topic) { last.textContent = 'Looking up: ' + topic; NS.dataChart.run(topic); return; }
      NS.ask(v, '').then(function (r) {
        if (!r.handled) last.textContent = 'Ignored (' + r.reason + '). Start with your name, for example: "' + NS.config.userName + ', how is the project going?"';
      });
    };
    yes.onclick = function () { NS.override('yes'); };
    no.onclick = function () { NS.override('no'); };
    NS.events.addEventListener('override-request', function (ev) { ovText.textContent = 'Asked: ' + ev.detail.question; ov.style.display = 'block'; });
    NS.events.addEventListener('override-done', function () { ov.style.display = 'none'; });
    NS.events.addEventListener('decision', function (ev) {
      const r = ev.detail;
      const label = r.action === 'held' ? 'Held for you' : r.action === 'answered' ? 'Answered (open)' : r.decision.answer.toUpperCase();
      last.textContent = label + ' \u00b7 ' + r.decision.confidence + '% \u00b7 ' + r.question;
    });
    NS.events.addEventListener('chart', function (ev) { last.textContent = 'Chart shown \u00b7 ' + ev.detail.chart.title + ' \u00b7 ' + ev.detail.chart.source; });
    drawStatus();
  }
  function drawStatus() {
    if (!ui) return;
    ui.status.textContent = (NS.listening ? 'Listening to captions' : 'Paused') + '. Answers go to the chat and the camera.';
    ui.toggle.textContent = NS.listening ? 'Pause' : 'Start';
  }

  window.standin = {
    start: function () { NS.captions.start(); NS.listening = true; drawStatus(); NS.log('listening to captions; answers go to the Meet chat and the camera'); },
    stop: function () { NS.captions.stop(); NS.listening = false; drawStatus(); NS.log('paused'); },
    ask: function (text) { return NS.ask(text, text); },
    // Show a chart of public data on the camera now, for example standin.chart('India GDP growth since 2015').
    chart: function (topic) { return NS.dataChart.run(topic); },
    research: function (topic) { return NS.research.run(topic); },
    transcript: function () { return NS.transcriptMarkdown(); },
    saveTranscript: function () { return NS.downloadTranscript(); },
    chatCheck: function () { return NS.chat.check(); },
    status: function () { return { listening: !!NS.listening, brain: NS.config.brain, threshold: NS.config.threshold, sent: NS.chat.sent.length, charts: NS.chartHistory.length, cameraCalls: NS.cameraCalls, slides: NS.slides.state() }; },
    config: NS.config,
    save: NS.saveConfig,
  };
  NS.slides.init();
  buildPanel();
  if (!ui) document.addEventListener('DOMContentLoaded', buildPanel, { once: true });
  if (NS.config.autoRelay) NS.openBridge();
  window.standin.start();
  NS.log('Now turn your Meet camera off and on once, so Meet picks up the slide camera.');
})();
